{
  "supplement_requests": [
    {
      "gap_id": "CH3_Gap_MTF_Evidence",
      "gap_question": "现有材料中 P0001 仅定性指出 Kho16 器件在离轴视场下 MTF 会迅速崩塌且旁瓣增强，但缺乏具体的定量偏差数据（如离轴几微米处的 MTF 下降比例或具体曲线形态）。为了在 CH3 中有力支撑‘不恰当比较’的论点并量化单界面几何像差对成像质量的实际影响，需要获取 Kho16 原文或其他高 NA 超构透镜在边缘视场（FOV > 2°或离轴距离>5µm）下的实测 MTF 数据或与理想衍射极限 MTF 的对比曲线。",
      "success_criteria": "提供 Kho16 或同类高 NA 可见光超构透镜在非中心视场（off-axis）的具体 MTF 数值、曲线图描述，或明确的实验结论表明其在特定空间频率下对比度相对于中心视场的衰减比例。若确无此类数据，需确认原始文献是否完全缺失该维度的表征，以便综述中明确将其列为评估标准的缺失项而非性能缺陷的证据。",
      "intended_use": "comparison",
      "targeted_queries": [
        {
          "query_type": "keyword",
          "query_text": "Khorasaninejad metalens MTF off-axis measurement data visible spectrum"
        },
        {
          "query_type": "question",
          "query_text": "What are the specific Modulation Transfer Function (MTF) values or curves for TiO2 metalenses at high NA (e.g., 0.8) at off-axis field positions compared to the diffraction limit?"
        }
      ],
      "chapter_ids": [
        "CH3"
      ]
    }
  ],
  "directed_reads": []
}

